/* Original generated photographic-style Sengoku field-battle artwork.
 * This is an invented atmospheric scene, not a photograph or a battle replay.
 * Embedded WebP keeps the standalone build and offline play self contained.
 */
(function (root) {
  "use strict";
  const FIELD_URI = "data:image/webp;base64,";
  function view(battle) {
    if (!battle || battle.mode !== "field") return null;
    return {
      uri: FIELD_URI,
      alt: "山と川、田畑を背景に足軽・騎馬・鉄砲隊が展開する野戦の実写風創作情景",
      caption: "実写風の創作情景。戦国期の野戦を題材にしたイメージで、現在の戦況・部隊配置を示す映像ではありません。",
      width: 1942,
      height: 809,
      artwork: "field-valley"
    };
  }
  root.TenkaBattleScenes = Object.freeze({ view, version: 1 });
})(typeof window !== "undefined" ? window : globalThis);
